script:
frappe.ui.form.on('Identity documents', {
    refresh(frm) {
        // Ajoute le bouton si un document est déjà présent au chargement
        if (frm.doc.document_upload && !frm.is_new()) {
            add_analyze_button(frm);
        }
    },

    document_upload(frm) {
        // Ajoute le bouton dès qu’un fichier est uploadé
        if (frm.doc.document_upload && !frm.is_new()) {
            add_analyze_button(frm);
        }
    }
});

function add_analyze_button(frm) {
    frm.add_custom_button('Analyser le document', () => {
        frappe.call({
            method: 'notaria.notaria.doctype.identity_documents.identity_documents.analyze_identity',
            args: {
                docname: frm.doc.name
            },
            callback: function (r) {
                if (!r.exc) {
                    frappe.show_alert('✅ Analyse terminée. Données extraites.');
                    frm.reload_doc();
                } else {
                    frappe.msgprint(__('❌ Une erreur est survenue pendant l’analyse.'));
                }
            }
        });
    }, 'Actions');
}

frappe.ui.form.on('Actes', {
  acte_modeles(frm) {
    if (frm.doc.acte_modeles) {
      frappe.db.get_doc('Actes_modeles', frm.doc.acte_modeles).then(doc => {
        frm.set_value('contenu_acte', doc.text);
      });
    }
  }
});

frappe.ui.form.on('Actes', {
  refresh: function(frm) {
    initialize_model_filter(frm);
  },

  type_acte: function(frm) {
    update_model_filter(frm);
    verify_model_consistency(frm);
  },

  acte_modeles: function(frm) {
    if (!frm.doc.acte_modeles) {
      frm.set_value('contenu_acte', '');
      return;
    }

    get_acte_model_content(frm);
  }
});

// ----------- FILTRES ------------

function initialize_model_filter(frm) {
  frm.set_query('acte_modeles', () => ({
    filters: {
      type_acte: frm.doc.type_acte || ''
    }
  }));
}

function update_model_filter(frm) {
  if (!frm.doc.type_acte) return;
  frm.set_query('acte_modeles', () => ({
    filters: {
      type_acte: frm.doc.type_acte
    }
  }));
}

function verify_model_consistency(frm) {
  if (frm.doc.acte_modeles && frm.doc.type_acte) {
    frappe.db.get_value('Actes_modeles', frm.doc.acte_modeles, 'type_acte', r => {
      if (r.message && r.message.type_acte !== frm.doc.type_acte) {
        frm.set_value('acte_modeles', '');
        frm.set_value('contenu_acte', '');
      }
    });
  }
}

frappe.ui.form.on('Actes', {
  async type_acte(frm) {
    if (!frm.doc.type_acte) return;

    const wrapper = frm.fields_dict.zone_variables?.$wrapper;
    if (!wrapper) {
      frappe.msgprint("Le champ HTML 'zone_variables' est introuvable.");
      return;
    }

    wrapper.empty();

    try {
      const type_acte_doc = await frappe.db.get_doc('type_acte', frm.doc.type_acte);

      for (const v of (type_acte_doc.variable || [])) {
        const var_name_raw = v.variable || v.variable_acte || '';
        if (!var_name_raw) continue;

        const var_name = var_name_raw.toLowerCase().replace(/[^a-z0-9_]/g, '_');

        // 🔍 Récupère les infos de la Variable Acte liée (dont description)
        const variable_doc = await frappe.db.get_doc('Variable Acte', var_name_raw);

        const label = variable_doc.description || var_name_raw;

        const $row = $(`
          <div class="mb-3">
            <label class="control-label">${label}</label>
            <input type="text" class="form-control" name="${var_name}" data-variable="${var_name_raw}">
          </div>
        `);

        wrapper.append($row);
      }

    } catch (err) {
      console.error("Erreur lors de la génération des variables :", err);
      frappe.msgprint("Erreur lors du chargement des variables.");
    }
  }
});

// Custom Script for DocType: Affaire notariale

// Fonction pour mettre à jour le champ client_principal
const updateClientPrincipal = () => {
    let clientFound = false;
    // Parcourir toutes les lignes de la table d'enfants 'involved_parties'
    for (let party of cur_frm.doc.involved_parties) {
        // Si le type de partie est "Client Principal"
        if (party.party_type === "Client Principal") {
            // Assigner la partie au champ client_principal de l'Affaire notariale
            // Assurez-vous que le champ 'party' dans 'Involved Party' est bien un Link vers 'Customer' ou votre DocType client
            cur_frm.set_value('client_principal', party.party);
            clientFound = true;
            break; // Arrêter après avoir trouvé le premier Client Principal
        }
    }
    // Si aucun client principal n'a été trouvé, vider le champ
    if (!clientFound) {
        cur_frm.set_value('client_principal', null);
    }
};

// 1. Déclencher la fonction lorsque le DocType est chargé (au cas où il y aurait déjà des parties)
frappe.ui.form.on('Affaire notariale', {
    onload: function(frm) {
        updateClientPrincipal();
    }
});

// 2. Déclencher la fonction à chaque modification de la table involved_parties
frappe.ui.form.on('Involved Party', {
    party_type: function(frm, cdt, cdn) {
        // Se déclenche si le type de partie est modifié dans une ligne existante
        updateClientPrincipal();
    },
    party: function(frm, cdt, cdn) {
        // Se déclenche si la partie (le lien client) est modifiée dans une ligne existante
        updateClientPrincipal();
    },
    involved_parties_remove: function(frm) {
        // Se déclenche lorsqu'une ligne est supprimée de la table
        updateClientPrincipal();
    },
    involved_parties_add: function(frm) {
        // Se déclenche lorsqu'une nouvelle ligne est ajoutée à la table
        updateClientPrincipal();
    }
});

frappe.ui.form.on('Affaire notariale', {
    refresh: function(frm) {
        if (!frm.doc.name) return;

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Actes",
                filters: {
                    affaire_notariale: frm.doc.name
                },
                fields: ["name", "type_acte", "creation_date", "status_acte"]
            },
            callback: function(r) {
                if (!r.message || r.message.length === 0) {
                    frm.fields_dict.actes_lies_html.$wrapper.html("<p>Aucun acte lié.</p>");
                    return;
                }

                let rows = r.message.map(actes => `
                    <tr>
                        <td><a href="/app/actes/${actes.name}">${actes.name}</a></td>
                        <td>${actes.type_acte || ""}</td>
                        <td>${actes.creation_date || ""}</td>
                        <td>${actes.status_acte || ""}</td>
                    </tr>
                `).join("");

                let html = `
                    <table class="table table-bordered">
                        <thead>
                            <tr>
                                <th>Nom</th>
                                <th>Type</th>
                                <th>Date</th>
                                <th>Statut</th>
                            </tr>
                        </thead>
                        <tbody>${rows}</tbody>
                    </table>
                `;

                frm.fields_dict.actes_lies_html.$wrapper.html(html);
            }
        });
    }
});

frappe.ui.form.on('Affaire notariale', {
    refresh: function(frm) {
        if (frm.doc.__islocal) return; // Ne pas afficher si l'affaire n'est pas encore enregistrée

        frm.add_custom_button(__('Créer un Acte'), function () {
            frappe.new_doc('Actes', {
                affaire_notariale: frm.doc.name,
                type_acte: "", // optionnel : préremplir un type
            });
        }, __('Actions'));
    }
});
